scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {

};
scwin.fn_SetCode = function() {debugger;
    scwin.gDepCd = $c.session.info("js_dep_cd");
    scwin.gEmpNo = $c.session.info("js_emp_no");
    scwin.gUpDepCd = $c.session.info("js_belngdepcd");
    if (scwin.gLdMktTp === '1' || scwin.gLdMktTp === '2' || scwin.gLdMktTp === '4' || scwin.gLdMktTp === '6') {
        $c.stf.setObjectValue(rdo_MKT_ID, scwin.gLdMktTp);
        $c.stf.showObj(panel_mkt, false);
    } else {
        $c.stf.setObjectValue(rdo_MKT_ID, '9');
    }

    //채권일 경우 채권상장폐지여부 제외 항목으로 보이게끔 수정 20170310
    if ($c.stf.getObjectValue(rdo_MKT_ID) === '4') {
        $c.stf.showObj(label_3, false);
        $c.stf.showObj(label_24, true);
    } else {
        $c.stf.showObj(label_3, true);
        $c.stf.showObj(label_24, false);
    }

    // 유가 공시팀(26**), 코스닥 공시팀(34**) => 일때만 보여준다.     
    // 코넥스 추가
    if ($c.session.info("js_dep_cd").substring(0, 2) === '26' || $c.session.info("js_dep_cd").substring(0, 2) === '34' || $c.session.info("js_dep_cd").substring(0, 2) === '3B') {
        $c.stf.showObj(panel_dep_emp, true);
        scwin.gDepCd = "UPTEAM";
    } else {
        $c.stf.showObj(panel_dep_emp, false);
    }

    //  기간 from~ to  셋팅	
    vCurDate = $c.utils.cGetToday("yyyymmdd");
    //edt_FromDate.text = cGetMinusDate2(vCurDate, 7); 	// 일주일전 날짜
    edt_FromDate.setValue(vCurDate); // 현재날짜
    edt_ToDate.setValue(vCurDate); // 현재날짜

    // 팀 리스트 박스(소속부서와 같은 상위부서인 팀)	
    //dts_dep.DataID = "/CodeAction.do?method=listDepCdCode&For=R";
    ////dts_dep.DataID = "/CodeAction.do?method=getDepUpCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + $c.session.info("js_dep_cd");

	//----W-Craft WebSquare 변환 확인: Reset----//
    ////dts_dep.Reset();

    //담당자 리스트 박스(소속부서와 같은 상위부서인 팀원)	
    ////dts_emp.DataID = "/CodeAction.do?method=getEmpNoDepCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + $c.session.info("js_dep_cd");

	//----W-Craft WebSquare 변환 확인: Reset----//
    ////dts_emp.Reset();

    // 업종 셋팅
    ////dts_IndTp.DataID = "/CodeAction.do?method=listStdIndtpCB" + "&inputMessageId=CODEVALUE_INOUT&outputMessageId=CODE_OUT" + "&For=R";

	//----W-Craft WebSquare 변환 확인: Reset----//
    ////dts_IndTp.Reset();
};


// 법인명이 있고 특정 다른 조건을 선택할때 메세지
scwin.fn_CheckComNmCond = function() {
    var vIsurCd = $c.stf.getObjectValue(txb_isur_cd);
    if (vIsurCd !== '') {
        alert("해당항목 선택시 법인코드(명)의 조건값이  초기화 됩니다.");
        $c.stf.setObjectValue(txb_isur_cd, '');
        $c.stf.setObjectValue(txb_com_abbrv, '');
        return;
    }
};



// 공시상세  목록검색 조건체크  : 사용자 클릭 -->
scwin.fn_CheckCond = async function() {
    var vIsurCd = $c.stf.getObjectValue(txb_isur_cd);
    var vFssUnqNm = $c.stf.getObjectValue(txb_FssUnqNm);
    var vFormCd = $c.stf.getObjectValue(txb_FormCd);
    var vFormNm = $c.stf.getObjectValue(txb_FormNm);
    var vRsnclssCnt = $c.stf.getObjectValue(txb_rsn_cnt);
    var vKeyword = $c.stf.getObjectValue(txb_keyword);

    /*
    if (vKeyword == '' ) {
    	if (vIsurCd == '' &&  vFssUnqNm == '' && vFormNm == '' 
    		&& (vRsnclssCnt =='' || vRsnclssCnt == '0') ) {
    		alert("법인코드(명), 제출의무자명, 공시제목, 사유분류 중 하나 이상을  입력하셔야 합니다." );
    		txb_isur_cd.focus();
    		return;	
    	}
    } 
    */

    // 일자 체크
    if ($c.stf.getObjectValue(edt_FromDate).length < 8) {
        alert("일자 올바르게 입력하십시오.");
        edt_FromDate.focus();
        return;
    }

    // 일자 체크
    if ($c.stf.getObjectValue(edt_ToDate).length < 8) {
        alert("일자 올바르게 입력하십시오.");
        edt_ToDate.focus();
        return;
    }
    if ($c.stf.compareFromToDate2(edt_FromDate, edt_ToDate) === false) {
        return;
    }


    // 4년 이상의 기간은 검색 할 수 없다
    /*
    var edt_FromDate_year = getObjectValue(edt_FromDate).substr(0,4);
    var edt_FromDate_month = getObjectValue(edt_FromDate).substr(4,2)-1;
    var edt_FromDate_day = getObjectValue(edt_FromDate).substr(6,2);
    var edt_FromDate_Date = new Date(edt_FromDate_year,edt_FromDate_month,edt_FromDate_day);

    var edt_ToDate_year = getObjectValue(edt_ToDate).substr(0,4);
    var edt_ToDate_month = getObjectValue(edt_ToDate).substr(4,2)-1;
    var edt_ToDate_day = getObjectValue(edt_ToDate).substr(6,2);
    var edt_ToDate_Date = new Date(edt_ToDate_year,edt_ToDate_month,edt_ToDate_day);
    var date_result = ( Date.parse(edt_ToDate_Date) - Date.parse(edt_FromDate_Date) ) / ( 1000*60*60*24 );

    if ( date_result > 1461) {
    	alert("검색기간은 4년 이상을 초과 할 수 없습니다." );
    	return;	
    }
    */



    // 보고서코그 체크
    if (vFormCd.length > 0 && vFormCd.length !== 5) {
        alert("보고서코드 5자리를 입력하십시오.");
        txb_FormCd.focus();
        return;
    }
    // 언어구분 체크
    if (scwin.getChkValue(chb_kor_yn) === 0 && scwin.getChkValue(chb_eng_yn) === 0) {
        alert("언어구분은 한개이상 선택하십시오.");
        chb_kor_yn.focus();
        return;
    }

    // 제출유형 체크
    if (scwin.getChkValue(chb_main_yn) === 0 && scwin.getChkValue(chb_atch_yn) === 0) {
        alert("제출유형은 한개이상 선택하십시오.");
        chb_main_yn.focus();
        return;
    }
    if (scwin.fn_chkAttchKeyword() === false) {
        return;
    }
    var sRsnClssCdList = "";
    var sFormUpclssCd;
    var sRsnClssCd;
    for (var i = 1; i <= dts_Dscl_Cond.getTotalRow(); i++) {
        sFormUpclssCd = dts_Dscl_Cond.getCellData(i, "FORM_UPCLSS_CD");
        sRsnClssCd = dts_Dscl_Cond.getCellData(i, "RSN_CLSS_CD");
        if (sRsnClssCd !== "000") {
            sRsnClssCdList += (sFormUpclssCd + sRsnClssCd + ",");
        }
    }

    // 맨뒤에 ", " 제거 하기 
    scwin.gRsnClssCdList = sRsnClssCdList.substr(0, sRsnClssCdList.length - 1);
    scwin.gDepCd = $c.stf.getObjectValue(cmb_TeamList);
    scwin.gEmpNo = $c.stf.getObjectValue(cmb_EmpList);
    if (scwin.gDepCd === "UPTEAM" && $c.session.info("js_dep_cd").substr(2, 4) === '00') {
        scwin.gUpDepCd = $c.session.info("js_dep_cd");
    }
    if ($c.session.info("js_dep_cd") === '3410') {
        // 코 공시제도팀인 공시총괄팀으로 설정-- 2010.03.11
        scwin.gUpDepCd = '3400';
    }
    scwin.fn_Search();
};



//  공시상세   목록검색 : 사용자 클릭 -->
scwin.fn_Search = async function() {debugger;
    // 조회 버튼 클릭 후 바로 버튼 클릭 안되게 처리 20150325
    btn_Search.setDisabled(true);
    ////btn_Search.src = "../img/btn_select_d.gif";
    scwin.vCurrPageNo = 0;
    ////dts_DsclList_excel.removeAll();
debugger;
    //공시본문검색은 채권해제법인제외 조건을 선택하지 못하게 한다.
    //검색엔진 테이블에 채권공시법인여부 칼럼이 없어서..
    if (txb_keyword.getValue() !== "") {
        if ($c.stf.getObjectValue(rdo_MKT_ID) === '4') {
            chb_ListStatCd.setValue(0);
        }
    }
    var url = "";
    var url_cond = "&ISUR_CD=" + $c.stf.getObjectValue(txb_isur_cd) + "&FROM_DATE=" + $c.stf.getObjectValue(edt_FromDate) + "&TO_DATE=" + $c.stf.getObjectValue(edt_ToDate) + "&DEP_CD=" + scwin.gDepCd + "&UP_DEP_CD=" + scwin.gUpDepCd + "&EMP_NO=" + scwin.gEmpNo + "&LIST_STAT=" + scwin.getChkValue(chb_ListStatCd) + "&LAST_YN=" + scwin.getChkValue(chb_Last) + "&BYPASS_YN=" + scwin.getChkValue(chb_ByPass) + "&FORM_CD=" + $c.stf.getObjectValue(txb_FormCd) + "&FORM_NM=" + $c.stf.getObjectValue(txb_FormNm) + "&KEYWORD=" + $c.stf.replaceAll($c.stf.getObjectValue(txb_keyword), "&", "＆") + "&FSS_UNQ_NO=" + $c.stf.getObjectValue(txb_FssUnqNo) + "&FSS_UNQ_NM=" + $c.stf.getObjectValue(txb_FssUnqNm) + "&ACNTCLS_MM=" + $c.stf.getObjectValue(cmb_month) + "&IND_TP=" + $c.stf.getObjectValue(cmb_IndTp) + "&KOR_YN=" + scwin.getChkValue(chb_kor_yn) + "&ENG_YN=" + scwin.getChkValue(chb_eng_yn) + "&LD_MKT_TP=" + $c.stf.getObjectValue(rdo_MKT_ID) + "&RSN_CLSS_CD_LIST=" + scwin.gRsnClssCdList + "&MAIN_YN=" + scwin.getChkValue(chb_main_yn) + "&ATCH_YN=" + scwin.getChkValue(chb_atch_yn) + "&DEP_TP=" + scwin.getChkValue(chb_dep_tp) + "&BASIS_TP=" + $c.stf.getObjectValue(cmb_Basis) + "&PAGENO=" + scwin.vCurrPageNo + "&PAGESIZE=" + scwin.pageSize + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + $c.stf.info("SCREN_PROCS_TP_CD_01");
    //alert(url_cond);

    scwin.gKeyword = $c.stf.getObjectValue(txb_keyword);
    if (scwin.gKeyword.length > 0) {
        //본문검색 키워드가있을때 ... 
        var iOpCnt = 0;
        if (scwin.gKeyword.indexOf("&") > 0) {
            iOpCnt = iOpCnt + 1;
        }
        if (scwin.gKeyword.indexOf("|") > 0) {
            iOpCnt = iOpCnt + 1;
        }
        if (scwin.gKeyword.indexOf("!") > 0) {
            iOpCnt = iOpCnt + 1;
        }
        if (iOpCnt > 1) {
            alert("본문검색 키워드는 한 개만 사용할 수 있습니다.");
            txb_keyword.focus();
            return;
        }
        if (scwin.pageSize === 0) {
            alert("공시본문내용으로 검색할 경우에는 한페이지당 보여주는 갯수를 '전체'로 사용할 수 없습니다.");
            $c.stf.setObjectValue(cmb_PerPage, "50");
            cmb_PerPage.focus();
            return;
        }
        $c.stf.showObj(mgrd_Grid, true);
        $c.stf.showObj(grd_Grid, false);
        ////$c.cm.ShowWin(mgrd_Grid);

        // 1. 검색 건수부터 조회한다.
        ////url = "/DisclosureSearch.do?method=countDsclDetailSrchEngine" + "&inputMessageId=DSCLDETAILCOND_IN" + "&outputMessageId=SCN_CNTSTAT_OUT";

        //alert("본문검색 카운트: "+url + url_cond);						
        ////dts_scn_list.DataID = encodeURI(url + url_cond);

	//----W-Craft WebSquare 변환 확인: reset----//
        ////dts_scn_list.reset();
	dts_scn_in.set("ISUR_CD", txb_isur_cd.getValue());
	dts_scn_in.set("FROM_DATE",  edt_FromDate.getValue());
	dts_scn_in.set("TO_DATE",  edt_ToDate.getValue());
	dts_scn_in.set("DEP_CD",  scwin.gDepCd);
	dts_scn_in.set("UP_DEP_CD",  scwin.gUpDepCd);
	dts_scn_in.set("EMP_NO",  scwin.gEmpNo);
	dts_scn_in.set("LIST_STAT",   chb_ListStatCd.getValue());
	dts_scn_in.set("LAST_YN",  chb_Last.getValue());
	dts_scn_in.set("BYPASS_YN",  chb_ByPass.getValue());	// 사전확인면제 조건 추가 by LDJ_20130422)
	dts_scn_in.set("FORM_CD="+ txb_FormCd.getValue());
	dts_scn_in.set("FORM_NM",  txb_FormNm.getValue());
	//dts_scn_in.set("KEYWORD",  txb_keyword.getValue());
	dts_scn_in.set("KEYWORD",  txb_keyword.getValue().replaceAll("&", "＆"));
	dts_scn_in.set("FSS_UNQ_NO",  txb_FssUnqNo.getValue());
	dts_scn_in.set("FSS_UNQ_NM",  txb_FssUnqNm.getValue());
	dts_scn_in.set("ACNTCLS_MM",  cmb_month.getValue());
	dts_scn_in.set("IND_TP",  cmb_IndTp.getValue());
	dts_scn_in.set("KOR_YN", chb_kor_yn.getValue());
	dts_scn_in.set("ENG_YN",  chb_eng_yn.getValue());
	dts_scn_in.set("LD_MKT_TP",  rdo_MKT_ID.getValue());
	//dts_scn_in.set("RSN_CLSS_CD_LIST",  gRsnClssCdList);  //ps.
	dts_scn_in.set("MAIN_YN", chb_main_yn.getValue());
	dts_scn_in.set("ATCH_YN",  chb_atch_yn.getValue()	);
	dts_scn_in.set("DEP_TP",  chb_dep_tp.getValue()	);
	dts_scn_in.set("BASIS_TP="+ cmb_Basis.getValue());
	dts_scn_in.set("PAGENO", scwin.vCurrPageNo);
	dts_scn_in.set("PAGESIZE",  scwin.pageSize);
	dts_scn_in.set("SCREN_ID",scwin.vScrenID);
	dts_scn_in.set("SCREN_PROCES_TP_CD", $c.stf.info("SCREN_PROCS_TP_CD_01"));

    	const resData = await $c.sbm.execute(sbm_countDsclDetailSrchEngine);
	//dts_DsclList.setJSON(resData.responseJSON);
debugger;
        var vScnCur = dts_scn_list.getCellData(dts_scn_list.getTotalRow() - 1, "SCN_CUR");
        //alert(dts_scn_list.CountRow +", "+vScnCur);	

        if (dts_scn_list.getTotalRow() > 0) {
            // 2.  Docruzer으로 검색
            ////url = "/DisclosureSearch.do?method=pagingDsclDetailSrchEngine" + "&inputMessageId=DSCLDETAILCOND_IN" + "&outputMessageId=DSCLDETAILLIST_OUT";
            url_cond += "&SCN_NM=" + vScnCur;
            //url_cond += "&SCN_NM=discls_internal";
            //alert("본문검색: "+url + url_cond);	

            //alert("url-->"+url + url_cond);

            ////dts_DsclList.DataID = encodeURI(url + url_cond);

	//----W-Craft WebSquare 변환 확인: reset----//
            ////dts_DsclList.reset();
            const resData = await $c.sbm.execute(sbm_pagingDsclDetailSrchEngine);
            //dts_DsclList.setJSON(resData.responseJSON);            
            $c.stf.showObj(panel_scn, true);
            $c.stf.showObj(panel_combo, true);
            $c.stf.showObj(mgrd_Grid, true);
            $c.stf.showObj(grd_Grid, false);
            ////$c.cm.ShowWin(mgrd_Grid);
        } else {
            // 조회 버튼 클릭 후 바로 버튼 클릭 안되게 처리 20150325
            btn_Search.setDisabled(true);
            ////btn_Search.src = "../img/btn_select.gif";
            scwin.vCurrPageNo = 0;
            ////dts_DsclList_excel.removeAll();
            ////dts_DsclList.removeAll();
            showObj(mgrd_Grid, true);	
            //showObj(grd_Grid, false);	
            $c.cm.CloseWin(0, mgrd_Grid);
        }
    } else {
        // 본문검색 키워드가 없을때 ... 일반 DB검색
        ////url = "/DisclosureSearch.do?method=pagingDsclDetailSrch" + "&inputMessageId=DSCLDETAILCOND_IN" + "&outputMessageId=DSCLDETAILLIST_OUT";
        ////dts_DsclList.DataID = encodeURI(url + url_cond);

	//----W-Craft WebSquare 변환 확인: reset----//
        ////dts_DsclList.reset();
    	const resData = await $c.sbm.execute(sbm_pagingDsclDetailSrch);
    	dts_DsclList.setJSON(resData.responseJSON);        
        $c.stf.showObj(panel_scn, false);
        $c.stf.showObj(panel_combo, false);
        $c.stf.showObj(mgrd_Grid, false);
        $c.stf.showObj(grd_Grid, true);
        $c.cm.ShowWin(grd_Grid);
    }
};
scwin.ScnarioNmCall = function(pScnNm) {debugger;
    scwin.vCurrPageNo = 0;
    var url = "";
    if (scwin.gKeyword.length > 0) {
        //본문검색 키워드가있을때 ... 

        if ($c.stf.getObjectValue(rdo_MKT_ID) === '4') {
            chb_ListStatCd.setValue(0);
        }
        // 2.  Docruzer으로 검색
        url = "/DisclosureSearch.do?method=pagingDsclDetailSrchEngine" + "&inputMessageId=DSCLDETAILCOND_IN" + "&outputMessageId=DSCLDETAILLIST_OUT";
    } else {
        url = "/DisclosureSearch.do?method=pagingDsclDetailSrch" + "&inputMessageId=DSCLDETAILCOND_IN" + "&outputMessageId=DSCLDETAILLIST_OUT";
    }
