scwin.dts_DsclList_excel_OnLoadCompleted = function(rowcount) {
    showload.style.display = "none";
    if (scwin.gExcelTp === "1") {
        //채권일경우 상장 제외 20170310
        if ($c.stf.getObjectValue(rdo_MKT_ID) === "4") {
            $c.cp.setColumnProp(grd_Grid_excel, "LIST_STAT_ID", 'Show', false);
            $c.cp.setColumnProp(grd_Grid_excel, "COM_ABBRV", 'color', "Black");
        }
        $c.data.downloadGridViewExcel(grd_Grid_excel, "공시상세검색  목록", "", "8");
    } else {
        var responseCode = dts_DsclList_excel.getCellData(1, "VALUE");
        var inside_email = dts_DsclList_excel.getCellData(1, "TEXT");
        if (responseCode === "200") {
            alert("1만건 이상은 메일로 제공합니다.\n엑셀저장이 완료되면 등록된 이메일(" + inside_email + ")로 엑셀파일 링크가 전송됩니다.\n(5만건 기준 약 1분 소요).");
        } else {
