scwin.cmb_TeamList_onselchange2 = function() {debugger;
    scwin.gDepCd = $c.cp.valueOfIndex(cmb_TeamList, "VALUE", cmb_TeamList.getSelectedIndex());
    if (scwin.gDepCd === '' || scwin.gDepCd === 'UPTEAM') {
        $c.stf.setObjectValue(cmb_EmpList, '');
    }

	//----W-Craft WebSquare 변환 확인: Filter----//
    ////dts_emp.UseFilter = true;

	//----W-Craft WebSquare 변환 확인: Filter----//
    ////dts_emp.Filter();

    var dataListId = cmb_EmpList.itemsetObj.nodeset;
    dataListId = dataListId.replaceAll("data:","");
    var dataListObj = $p.getComponentById(dataListId);

    dataListObj.removeColumnFilterAll();

    function fn_tmpDeptFilter(cellData, tmpParam, row) {
        //  부서코드에  해당하는 사원을 가져온다.
        if (scwin.gDepCd === "" || scwin.gDepCd === "UPTEAM" ) {	// 전체일 경우 모두 보여준다.
            return true;
        } else {
            if (dataListObj.getCellData(row, "DEP_CD") === scwin.gDepCd
                ||dataListObj.getCellData(row, "DEP_CD") === "UPTEAM" 
                || dataListObj.getCellData(row, "DEP_CD") === "") {
                return true;
            } else {
                return false;
            }
        }	
    }
    //var filterOptions = {type:'func', colIndex:'DEP_CD', key:fn_tmpDeptFilter, condition:'and'};
    var filterOptions = {type:'func', colIndex:'DEP_CD', key:scwin.dts_emp_OnFilter, condition:'and'};
    dataListObj.setColumnFilter(filterOptions);

	if (scwin.gDepCd !=='' && scwin.gDepCd !=='UPTEAM') {
		//cmb_EmpList.ShowList();
        cmb_EmpList.trigger("onclick");
	}


    dts_emp.sort("DEP_CD", 0);
    //dts_emp.sort(); // W-Craft 주석처리 
    if (scwin.gDepCd !== '' && scwin.gDepCd !== 'UPTEAM') {
        cmb_EmpList.trigger("onclick");
    }
};
